package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.app.*;import android.content.res.Configuration;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w360dp-h780dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class V087RegressionTest {
 private AppRegressionTest base;private MainActivity a;private VehicleCoordinator model;
 @Before public void start()throws Exception{base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);a=(MainActivity)f.get(base);model=VehicleCoordinator.get(a);set(model,"signedIn",true);model.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();model.selected.vin="FIXTURE-V087";model.snapshot=sample();AppPreferences.set(a,"language","zh");}
 @After public void stop(){AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();if(d!=null)d.dismiss();base.stop();}
 private void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 private void invoke(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);}
 private VehicleSnapshot sample(){long now=System.currentTimeMillis();return new VehicleSnapshot("Polestar 2","masked",63,230,65845,"充电中","全部关闭","全部关闭","已关闭","已上锁",now,"LIVE",false,"关闭","关闭").withHealth(new VehicleHealthSnapshot(1,1,1,now,1,1,1,-1,1,931,75,14959)).withCharging(new ChargingSnapshot(1,2,4,80,6000.0,25.0));}
 private View root(){return a.getWindow().getDecorView();}
 private View tag(String key){View v=root().findViewWithTag(key);assertNotNull(key,v);return v;}
 private View render(int w,int h,float font)throws Exception{Configuration c=new Configuration(a.getResources().getConfiguration());c.screenWidthDp=w;c.screenHeightDp=h;c.fontScale=font;android.util.DisplayMetrics d=a.getResources().getDisplayMetrics();d.scaledDensity=d.density*font;a.getResources().updateConfiguration(c,d);invoke("render");View v=root();v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);return v;}
 private void fit(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.length()>0&&t.getLayout()!=null)assertTrue(t.getText()+" height="+t.getHeight()+" layout="+t.getLayout().getHeight(),t.getLayout().getHeight()<=t.getHeight()-t.getCompoundPaddingTop()-t.getCompoundPaddingBottom());}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)fit(((ViewGroup)v).getChildAt(i));}
 @Test public void nativeConditionTextIsPaintedInEveryModeSkinLanguageAndTheme()throws Exception{for(String skin:UiSkin.CHOICES)for(String mode:new String[]{"bar","percent","text"})for(String theme:new String[]{"light","dark"})for(String lang:new String[]{"zh","en"}){UiSkin.set(a,skin);AppPreferences.set(a,"condition_display",mode);AppPreferences.set(a,"theme",theme);AppPreferences.set(a,"language",lang);render(360,780,1);VehicleConditionButton b=(VehicleConditionButton)tag("exterior_button");assertNotNull(b.getLayout());assertTrue(b.getText().toString().startsWith(lang.equals("zh")?"车况":"Status"));assertEquals(0,b.getScrollX());Bitmap image=Bitmap.createBitmap(b.getWidth(),b.getHeight(),Bitmap.Config.ARGB_8888);b.draw(new Canvas(image));int pixels=0,color=b.getCurrentTextColor();int top=b.getBaseline()-b.getLayout().getLineBaseline(0);for(int y=Math.max(0,top);y<Math.min(b.getHeight()-b.getPaddingBottom(),top+b.getLayout().getLineBottom(0));y++)for(int x=5;x<b.getWidth()-5;x++){int c=image.getPixel(x,y);if(Math.abs(Color.red(c)-Color.red(color))+Math.abs(Color.green(c)-Color.green(color))+Math.abs(Color.blue(c)-Color.blue(color))<35)pixels++;}assertTrue(skin+" "+mode+" "+theme+" "+lang,pixels>3);image.recycle();}}
 @Test public void defaultInactiveControlsUseDarkSurfaceAndLightInk()throws Exception{UiSkin.set(a,UiSkin.PS_DEFAULT);AppPreferences.set(a,"theme","dark");render(360,780,1);for(String kind:new String[]{"lock","trunk","climate","air"}){TextView title=(TextView)tag("control_title_"+kind);View v=title;while(!"control_tile".equals(v.getTag()))v=(View)v.getParent();assertEquals(PsaDesign.surface(true),((GradientDrawable)v.getBackground()).getColor().getDefaultColor());assertEquals(PsaDesign.ink(true),title.getCurrentTextColor());}}
 @Test public void defaultUtilitiesRetainFourAlignedIconsInAllDisplayModes()throws Exception{UiSkin.set(a,UiSkin.PS_DEFAULT);for(String mode:new String[]{"bar","percent","text"}){AppPreferences.set(a,"condition_display",mode);render(360,780,1);int expected=-1;for(String key:new String[]{"windows_control_button","exterior_button","camp_button","signal_control_button"}){TextView v=(TextView)tag(key);Drawable glyph=v.getCompoundDrawablesRelative()[1];assertNotNull(mode+" "+key,glyph);assertEquals(18,glyph.getBounds().height());assertEquals(tag("camp_button").getHeight(),v.getHeight());int top=v.getTotalPaddingTop()-(v.getCompoundPaddingTop()-v.getPaddingTop());if(expected<0)expected=top;assertTrue(mode+" "+key+" "+expected+"/"+top,Math.abs(expected-top)<=1);}}}
 @Test public void allThreeNavigationTabsHaveARealIconInEverySkin()throws Exception{for(String skin:UiSkin.CHOICES){UiSkin.set(a,skin);render(360,780,1);ViewGroup nav=(ViewGroup)tag("bottom_nav");for(int i=0;i<3;i++){TextView t=(TextView)nav.getChildAt(i);assertNotNull(t.getCompoundDrawables()[1]);assertTrue(t.getCompoundDrawables()[1].getBounds().height()>0);}}}
 @Test public void carTapsAndConditionButtonsUseTheSameSecondaryPopup()throws Exception{for(String skin:UiSkin.CHOICES){UiSkin.set(a,skin);render(360,780,1);tag("polestar_vehicle").performClick();AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(dialog.findViewById(android.R.id.content).findViewWithTag("car_condition_popup"));Field page=MainActivity.class.getDeclaredField("page");page.setAccessible(true);assertEquals(0,page.getInt(a));dialog.dismiss();tag("exterior_button").performClick();AlertDialog status=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(status.findViewById(android.R.id.content).findViewWithTag("car_condition_popup"));assertEquals(0,page.getInt(a));status.dismiss();}}
 @Test public void lightSwitchesAreAvailableInSettings()throws Exception{set(a,"page",2);AppPreferences.set(a,"expand_settings_effects","on");render(360,780,1);assertNotNull(tag("light_effects"));assertNotNull(tag("all_good_shimmer"));assertNotNull(tag("charging_animation"));}
 @Test public void goodSweepStopsOnPauseDisabledPreferenceAndWarning()throws Exception{UiSkin.set(a,UiSkin.PS_DEFAULT);render(360,780,1);ViewGroup status=(ViewGroup)tag("vehicle_status_button");AllGoodTextView label=(AllGoodTextView)status.getChildAt(1);Field animator=AllGoodTextView.class.getDeclaredField("animator");animator.setAccessible(true);AllGoodTextView.host(root(),false);assertNull(animator.get(label));AllGoodTextView.host(root(),true);android.animation.ValueAnimator running=(android.animation.ValueAnimator)animator.get(label);if(running!=null)assertEquals(6400,running.getDuration());label.setText("Check vehicle");assertNull(animator.get(label));AppPreferences.set(a,"light_effects","off");label.setText("All Good！");assertNull(animator.get(label));}
 @Test public void typographyAndIconsFitSmallAndLandscapeScreens()throws Exception{for(String skin:UiSkin.CHOICES)for(String theme:new String[]{"dark","light"})for(int[] size:new int[][]{{320,568},{640,320}}){UiSkin.set(a,skin);AppPreferences.set(a,"theme",theme);try{fit(render(size[0],size[1],1.56f));}catch(AssertionError e){throw new AssertionError(skin+" "+theme+" "+Arrays.toString(size),e);}}}
 @Test public void trialTargetDefaultsOffAndInvalidPreferencesCannotLeaveBounds(){assertFalse(ClimateTarget.enabled(a));AppPreferences.set(a,"climate_target_c","24");assertEquals(22f,ClimateTarget.request(a),0);AppPreferences.set(a,"climate_custom_target","on");assertEquals(24f,ClimateTarget.request(a),0);AppPreferences.set(a,"climate_target_c","99");assertEquals(22f,ClimateTarget.request(a),0);}
 @Test public void campingCapturesTemperatureAndOldSessionsKeepTwentyTwo(){CampSession old=new CampSession("old","fixture","car",1000,31,10,false);assertEquals(22f,old.targetTemperatureC,0);assertFalse(old.verifyClimateTarget);CampSession trial=new CampSession("trial","fixture","car",1000,31,10,false,24f);assertEquals(24f,trial.targetTemperatureC,0);assertTrue(trial.verifyClimateTarget);}
 @Test public void targetConfirmationRejectsOldUnknownOrMismatchingReports(){long now=System.currentTimeMillis();VehicleSnapshot v=sample().withEnvironment(new EnvironmentSnapshot("开启","关闭",30.0,24.0,null,null,20,0,now,now));assertTrue(ClimateTarget.confirmed(v,24f,now));assertFalse(ClimateTarget.confirmed(v,22f,now));assertFalse(ClimateTarget.confirmed(v,24f,now+1));assertFalse(ClimateTarget.confirmed(sample(),22f,now));}
 @Test public void powerSaverStopsGoodTextEvenWhenItRemainsVisible()throws Exception{UiSkin.set(a,UiSkin.PS_DEFAULT);render(360,780,1);AllGoodTextView label=(AllGoodTextView)((ViewGroup)tag("vehicle_status_button")).getChildAt(1);PowerManager manager=(PowerManager)a.getSystemService(android.content.Context.POWER_SERVICE);Shadows.shadowOf(manager).setIsPowerSaveMode(true);a.sendBroadcast(new android.content.Intent(PowerManager.ACTION_POWER_SAVE_MODE_CHANGED));org.robolectric.shadows.ShadowLooper.shadowMainLooper().idle();Field f=AllGoodTextView.class.getDeclaredField("animator");f.setAccessible(true);assertNull(f.get(label));}
 @Test public void carPopupRestoresBackgroundGoodAnimationOnDismiss()throws Exception{UiSkin.set(a,UiSkin.PS_DEFAULT);render(360,780,1);AllGoodTextView label=(AllGoodTextView)((ViewGroup)tag("vehicle_status_button")).getChildAt(1);Field host=AllGoodTextView.class.getDeclaredField("hostActive");host.setAccessible(true);tag("polestar_vehicle").performClick();assertFalse(host.getBoolean(label));org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().dismiss();org.robolectric.shadows.ShadowLooper.shadowMainLooper().idle();assertTrue(host.getBoolean(label));}
 private void export(String name)throws Exception{View v=render(360,780,1);File f=new File("build/reports/previews/v087/"+name+".png");f.getParentFile().mkdirs();Bitmap b=Bitmap.createBitmap(720,1560,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.scale(2,2);v.draw(c);try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Test public void exportsImplementedDayNightAndPopupScreens()throws Exception{UiSkin.set(a,UiSkin.PS_DEFAULT);AppPreferences.set(a,"theme","light");export("ps-default-day");AppPreferences.set(a,"theme","dark");export("ps-default-night");tag("polestar_vehicle").performClick();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();View v=((ScrollView)d.findViewById(android.R.id.content).findViewWithTag("car_condition_popup")).getChildAt(0);v.setBackgroundColor(PsaDesign.canvas(true));v.measure(View.MeasureSpec.makeMeasureSpec(340,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(620,View.MeasureSpec.AT_MOST));v.layout(0,0,v.getMeasuredWidth(),v.getMeasuredHeight());File f=new File("build/reports/previews/v087/car-popup.png");Bitmap b=Bitmap.createBitmap(v.getWidth()*2,v.getHeight()*2,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.scale(2,2);v.draw(c);try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
